import{_ as s,c as e,o as a,ag as n}from"./chunks/framework.ymCRTBvy.js";const c=JSON.parse('{"title":"8.4_设置fillMode与removedOnCompletion","description":"","frontmatter":{},"headers":[],"relativePath":"uikit/uikit_animation/8.4_设置fillMode与removedOnCompletion.md","filePath":"uikit/uikit_animation/8.4_设置fillMode与removedOnCompletion.md"}'),o={name:"uikit/uikit_animation/8.4_设置fillMode与removedOnCompletion.md"};function l(t,i,d,r,p,h){return a(),e("div",null,i[0]||(i[0]=[n(`<h1 id="_8-4-设置fillmode与removedoncompletion" tabindex="-1">8.4_设置fillMode与removedOnCompletion <a class="header-anchor" href="#_8-4-设置fillmode与removedoncompletion" aria-label="Permalink to &quot;8.4_设置fillMode与removedOnCompletion&quot;">​</a></h1><h2 id="理解动画的生命周期" tabindex="-1">理解动画的生命周期 <a class="header-anchor" href="#理解动画的生命周期" aria-label="Permalink to &quot;理解动画的生命周期&quot;">​</a></h2><p>在iOS动画中，<code>fillMode</code> 和 <code>removedOnCompletion</code> 是两个至关重要的属性，它们共同决定了动画在执行完毕后的行为。掌握它们能让你对动画的控制力达到一个新的高度！🚀</p><p>当你创建一个 <code>CAAnimation</code> 实例并将其添加到 <code>CALayer</code> 上时，动画会按照你设定的时间曲线和持续时间运行。然而，动画结束后，图层会恢复到其模型层（Model Layer）的属性值。这常常导致动画“跳回”到初始状态，这可不是我们想要的！</p><h2 id="fillmode-的魔力" tabindex="-1">fillMode 的魔力 <a class="header-anchor" href="#fillmode-的魔力" aria-label="Permalink to &quot;fillMode 的魔力&quot;">​</a></h2><p><code>fillMode</code> 属性决定了动画在非活动时间（即动画开始前和结束后）如何影响图层。它有四个可选值，每个都带来不同的效果：</p><ul><li><strong><code>forwards</code></strong>: 动画结束后，图层会保持动画的最终状态。这是最常用的模式之一，因为它能让你的动画效果持久化。</li><li><strong><code>backwards</code></strong>: 动画开始前，图层会立即跳到动画的起始状态。这在某些预加载动画中非常有用。</li><li><strong><code>both</code></strong>: 结合了 <code>forwards</code> 和 <code>backwards</code> 的效果，动画开始前保持起始状态，结束后保持最终状态。</li><li><strong><code>removed</code></strong>: 这是默认值。动画结束后，图层会恢复到其模型层的原始状态。</li></ul><p>例如，如果你想让一个视图移动到屏幕右侧并停留在那里，你一定会设置 <code>fillMode</code> 为 <code>forwards</code>。想象一下，一个按钮优雅地滑入视图并固定在那里，是不是很棒？✨</p><h2 id="removedoncompletion-的作用" tabindex="-1">removedOnCompletion 的作用 <a class="header-anchor" href="#removedoncompletion-的作用" aria-label="Permalink to &quot;removedOnCompletion 的作用&quot;">​</a></h2><p><code>removedOnCompletion</code> 属性是一个布尔值，默认为 <code>true</code>。它控制着动画在执行完毕后是否从图层上移除。</p><ul><li><strong><code>true</code></strong>: 动画执行完毕后，会自动从图层上移除。如果 <code>fillMode</code> 设置为 <code>forwards</code>，图层会保持动画的最终状态，但动画对象本身会被销毁。</li><li><strong><code>false</code></strong>: 动画执行完毕后，会继续保留在图层上。这在需要手动控制动画移除的场景中非常有用，例如，当你需要暂停或恢复动画时。</li></ul><p>通常情况下，我们会将 <code>removedOnCompletion</code> 设置为 <code>false</code>，并配合 <code>fillMode = .forwards</code> 来确保动画结束后视图停留在最终位置。这样，动画效果就能完美地“冻结”在最后一帧。</p><h2 id="实践中的组合应用" tabindex="-1">实践中的组合应用 <a class="header-anchor" href="#实践中的组合应用" aria-label="Permalink to &quot;实践中的组合应用&quot;">​</a></h2><p>让我们看一个实际的例子。假设你有一个视图，想让它从屏幕左侧移动到右侧，并在右侧停留。</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">let</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> animation </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> CABasicAnimation</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">keyPath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;position.x&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">animation.fromValue </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">animation.toValue </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 300</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">animation.duration </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1.0</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">animation.fillMode </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .forwards </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 动画结束后保持最终状态</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">animation.isRemovedOnCompletion </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> // 动画不从图层移除</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">myView.layer.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(animation, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">forKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;moveX&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>这段代码将确保 <code>myView</code> 移动到 x 坐标 300 的位置后，会一直停留在那里，不会跳回原点。这正是我们想要的持久化效果！</p><h2 id="提升用户体验的关键" tabindex="-1">提升用户体验的关键 <a class="header-anchor" href="#提升用户体验的关键" aria-label="Permalink to &quot;提升用户体验的关键&quot;">​</a></h2><p>正确使用 <code>fillMode</code> 和 <code>removedOnCompletion</code> 可以极大地提升你的应用的用户体验。一个流畅、自然的动画效果能让用户感到愉悦，并对你的应用留下深刻印象。</p><ul><li><strong>避免闪烁</strong>: 动画结束后立即跳回原点会造成视觉上的闪烁，影响用户体验。</li><li><strong>保持状态</strong>: 许多UI元素在动画后需要保持其最终状态，例如一个展开的菜单或一个移动到新位置的图标。</li><li><strong>更精细的控制</strong>: 当你需要更复杂的动画链或交互时，将 <code>removedOnCompletion</code> 设置为 <code>false</code> 可以让你对动画的生命周期有更细致的掌控。</li></ul><p>记住，动画不仅仅是视觉上的花哨，更是提升应用可用性和用户满意度的强大工具。掌握这些核心概念，你就能创造出令人惊叹的动画效果！🚀✨</p>`,20)]))}const m=s(o,[["render",l]]);export{c as __pageData,m as default};
